referenceSolutions.javascript:
export function findAnagrams(text        , pattern        )           {
const need         =Array(26).fill(0),have         =Array(26).fill(0),out         =[];for(const c of pattern)need[c.charCodeAt(0)-97]++;for(let i=0;i<text.length;i++){have[text.charCodeAt(i)-97]++;if(i>=pattern.length)have[text.charCodeAt(i-pattern.length)-97]--;if(i>=pattern.length-1&&have.every((n,j)=>n===need[j]))out.push(i-pattern.length+1);}return out;
}

